def is_palindrome(s: str) -> bool:
    l, r = 0, len(s) - 1
    while l < r:
        if s[l] != s[r]:
            return False
        l += 1
        r -= 1
    return True

def is_palindrome_rec(s: str, l: int = 0, r: int | None = None) -> bool:
    if r is None:
        r = len(s) - 1
    if l >= r:
        return True
    if s[l] != s[r]:
        return False
    return is_palindrome_rec(s, l + 1, r - 1)
